(() => {
 const d=window.SWIFT_MALAY_DAILY_LEARNING;
 d.topics.push(...[{"id":"ms-topic-family-roles-02","topicId":"ms-topic-family-roles","difficulty":"beginner","title":"Hubungan kekeluargaan","titleEn":"Family relationships","titleZh":"家庭关系","body":"Istilah seperti ibu, bapa, adik-beradik, datuk dan nenek menerangkan hubungan dalam keluarga. Gunakan kata pemilikan untuk menjelaskan hubungan, contohnya ibu saya atau abang Ali.","en":"Terms such as mother, father, siblings, grandfather and grandmother describe family relationships. Use possessive forms to clarify relationships, such as ibu saya or abang Ali.","zh":"母亲、父亲、兄弟姐妹、祖父和祖母等词语描述家庭关系。使用所属表达说明关系，例如ibu saya或abang Ali。","example":"Adik saya sedang belajar di bilik.","exampleEn":"My younger sibling is studying in the room.","exampleZh":"我的弟弟/妹妹正在房间里学习。"},{"id":"ms-topic-home-spaces-02","topicId":"ms-topic-home-spaces","difficulty":"beginner","title":"Ruang di rumah","titleEn":"Spaces at home","titleZh":"家居空间","body":"Ruang seperti dapur, ruang tamu, bilik tidur dan halaman mempunyai fungsi yang berbeza. Gunakan kata sendi di untuk menyatakan lokasi sesuatu benda atau aktiviti.","en":"Spaces such as the kitchen, living room, bedroom and yard have different functions. Use the preposition di to state where an object or activity is located.","zh":"厨房、客厅、卧室和院子等空间有不同用途。使用介词di说明物品或活动的位置。","example":"Kami makan malam di ruang makan.","exampleEn":"We have dinner in the dining area.","exampleZh":"我们在用餐区吃晚饭。"},{"id":"ms-topic-food-meals-02","topicId":"ms-topic-food-meals","difficulty":"beginner","title":"Makanan dan waktu makan","titleEn":"Food and mealtimes","titleZh":"食物与用餐时间","body":"Sarapan, makan tengah hari dan makan malam merujuk waktu makan. Nama makanan seperti nasi, roti, sayur dan buah membantu anda menerangkan pilihan makanan.","en":"Sarapan, makan tengah hari and makan malam refer to mealtimes. Food words such as rice, bread, vegetables and fruit help describe food choices.","zh":"Sarapan、makan tengah hari和makan malam表示不同用餐时间。nasi、roti、sayur和buah等词汇有助于描述饮食选择。","example":"Saya biasanya bersarapan sebelum pergi bekerja.","exampleEn":"I usually have breakfast before going to work.","exampleZh":"我通常在上班前吃早餐。"},{"id":"ms-topic-time-duration-02","topicId":"ms-topic-time-duration","difficulty":"beginner","title":"Masa dan tempoh","titleEn":"Time and duration","titleZh":"时间与时长","body":"Pukul digunakan untuk menyatakan waktu pada jam, manakala selama menyatakan tempoh. Bezakan pukul lapan dengan selama dua jam.","en":"Pukul states a clock time, while selama expresses duration. Distinguish pukul lapan from selama dua jam.","zh":"Pukul用于表示钟点时间，selama用于表示持续时长。要区分pukul lapan（八点）和selama dua jam（两个小时）。","example":"Mesyuarat bermula pada pukul sembilan dan berlangsung selama sejam.","exampleEn":"The meeting starts at nine and lasts for an hour.","exampleZh":"会议九点开始，持续一个小时。"},{"id":"ms-topic-meN-prefix-02","topicId":"ms-topic-meN-prefix","difficulty":"intermediate","title":"Awalan meN- dan perubahan kata dasar","titleEn":"The meN- prefix and root changes","titleZh":"meN-前缀与词根变化","body":"Awalan meN- mengalami perubahan bentuk mengikut huruf awal kata dasar. Contohnya, membaca, menulis, menyapu dan mengira. Bentuk yang tepat perlu dipelajari bersama kata dasarnya.","en":"The meN- prefix changes form according to the initial sound of the root, as in membaca, menulis, menyapu and mengira. Learn the correct form together with its root.","zh":"meN-前缀会根据词根的首音改变形式，例如membaca、menulis、menyapu和mengira。应将正确形式与词根一起学习。","example":"Mereka mengira jumlah buku sebelum menyusunnya.","exampleEn":"They count the number of books before arranging them.","exampleZh":"他们在整理书籍前先计算数量。"},{"id":"ms-topic-voice-forms-02","topicId":"ms-topic-voice-forms","difficulty":"intermediate","title":"Ayat aktif dan ayat pasif","titleEn":"Active and passive sentences","titleZh":"主动句与被动句","body":"Ayat aktif menonjolkan pelaku yang melakukan tindakan. Ayat pasif pula menonjolkan perkara atau objek yang menerima tindakan. Pilih bentuk berdasarkan fokus maklumat.","en":"An active sentence foregrounds the doer. A passive sentence foregrounds the thing or object receiving the action. Choose the form according to the information focus.","zh":"主动句突出动作执行者；被动句突出接受动作的事物或对象。应根据表达重点选择句式。","example":"Pekerja itu membaiki komputer. Komputer itu dibaiki oleh pekerja tersebut.","exampleEn":"The worker repairs the computer. The computer is repaired by the worker.","exampleZh":"工作人员修理电脑。电脑由该工作人员修理。"},{"id":"ms-topic-prepositions-02","topicId":"ms-topic-prepositions","difficulty":"intermediate","title":"Kata sendi nama dalam konteks","titleEn":"Prepositions in context","titleZh":"语境中的介词","body":"Kata sendi nama seperti di, ke, dari, daripada dan kepada membawa fungsi yang berbeza. Di lazimnya menandakan tempat, ke arah atau destinasi, manakala kepada merujuk penerima.","en":"Prepositions such as di, ke, dari, daripada and kepada have different functions. Di commonly marks location, ke direction or destination, and kepada a recipient.","zh":"di、ke、dari、daripada和kepada等介词功能不同。di通常表示地点，ke表示方向或目的地，kepada表示接收者。","example":"Surat itu dihantar kepada pengurus di pejabat.","exampleEn":"The letter was sent to the manager at the office.","exampleZh":"那封信被送给办公室里的经理。"},{"id":"ms-topic-paragraph-cohesion-02","topicId":"ms-topic-paragraph-cohesion","difficulty":"advanced","title":"Kesatuan dan kesinambungan perenggan","titleEn":"Paragraph unity and cohesion","titleZh":"段落统一性与衔接","body":"Perenggan yang berkesan mempunyai satu idea utama yang dikembangkan dengan huraian dan bukti yang relevan. Penanda wacana membantu hubungan antara ayat, tetapi tidak menggantikan aliran idea yang logik.","en":"An effective paragraph develops one main idea with relevant explanation and evidence. Discourse markers help connect sentences but cannot replace logical progression.","zh":"有效段落围绕一个中心思想展开，并提供相关解释和证据。语篇衔接词有助于连接句子，但不能取代逻辑连贯性。","example":"Setiap perenggan perlu menyumbang kepada hujah keseluruhan tanpa mengulang isi yang sama.","exampleEn":"Each paragraph should contribute to the overall argument without repeating the same point.","exampleZh":"每个段落都应为整体论证作出贡献，避免重复相同内容。"},{"id":"ms-topic-argument-evidence-02","topicId":"ms-topic-argument-evidence","difficulty":"advanced","title":"Hujah, bukti dan inferens","titleEn":"Arguments, evidence and inference","titleZh":"论点、证据与推论","body":"Hujah menyatakan pendirian yang perlu disokong oleh bukti. Inferens ialah kesimpulan yang dibuat berdasarkan bukti dan penaakulan, bukan andaian yang tidak diperiksa.","en":"An argument states a position that needs evidence. An inference is a conclusion drawn from evidence and reasoning, not an unchecked assumption.","zh":"论点表达需要证据支持的立场。推论是根据证据和推理得出的结论，而不是未经检验的假设。","example":"Data kehadiran menunjukkan peningkatan; hal ini mungkin mencerminkan keberkesanan program, tetapi faktor lain juga perlu diteliti.","exampleEn":"Attendance data shows an increase; this may reflect the programme's effectiveness, but other factors should also be examined.","exampleZh":"出勤数据有所增加，这可能反映项目有效，但也需要研究其他因素。"}]);
 d.applications.push(...[{"id":"ms-application-describe-home-02","topicId":"ms-describe-home","difficulty":"beginner","title":"Terangkan lokasi di rumah","titleEn":"Describe locations at home","titleZh":"描述家中位置","body":"Berikan tiga petunjuk lokasi untuk membantu seseorang mencari objek di rumah. Gunakan di, di atas, di bawah atau di sebelah dengan jelas.","en":"Give three location clues to help someone find an object at home. Use di, di atas, di bawah or di sebelah clearly.","zh":"给出三个位置提示，帮助别人找到家中的物品。清楚使用di、di atas、di bawah或di sebelah。","example":"Kunci berada di atas meja, di sebelah pasu bunga.","exampleEn":"The key is on the table, beside the flower vase.","exampleZh":"钥匙在桌子上，花瓶旁边。","questions":[{"q":{"ms":"Frasa manakah menunjukkan lokasi di bahagian bawah?","en":"Which phrase indicates a location underneath?","zh":"哪个短语表示在下方？"},"options":[{"ms":"di bawah","en":"underneath","zh":"下方"},{"ms":"di atas","en":"above","zh":"上方"},{"ms":"di hadapan","en":"in front","zh":"前面"},{"ms":"di luar","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-daily-plan-02","topicId":"ms-daily-plan","difficulty":"beginner","title":"Susun jadual harian","titleEn":"Arrange a daily schedule","titleZh":"安排每日行程","body":"Susun empat aktiviti mengikut urutan masa. Gunakan penanda seperti pada waktu pagi, kemudian, selepas itu dan pada waktu malam.","en":"Arrange four activities in time order. Use markers such as in the morning, kemudian, selepas itu and at night.","zh":"按时间顺序安排四项活动。使用pada waktu pagi、kemudian、selepas itu和pada waktu malam等表达。","example":"Pada waktu pagi saya bersenam. Selepas itu, saya bersarapan.","exampleEn":"I exercise in the morning. After that, I have breakfast.","exampleZh":"早上我锻炼身体。之后，我吃早餐。","questions":[{"q":{"ms":"Ungkapan manakah paling sesuai untuk memperkenalkan aktiviti seterusnya?","en":"Which expression best introduces the next activity?","zh":"哪个表达最适合引出下一项活动？"},"options":[{"ms":"Selepas itu","en":"underneath","zh":"下方"},{"ms":"Walaupun begitu","en":"above","zh":"上方"},{"ms":"Sebaliknya","en":"in front","zh":"前面"},{"ms":"Kesimpulannya","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-food-order-02","topicId":"ms-food-order","difficulty":"beginner","title":"Buat pesanan makanan","titleEn":"Order food","titleZh":"点餐","body":"Bina dialog ringkas untuk memesan makanan. Nyatakan hidangan, kuantiti dan minuman dengan bahasa yang sopan.","en":"Create a short dialogue to order food. State the dish, quantity and drink politely.","zh":"编写一段简短对话来点餐。礼貌地说明菜品、数量和饮料。","example":"Saya ingin memesan nasi goreng satu dan air kosong, boleh?","exampleEn":"I would like to order one fried rice and plain water, please.","exampleZh":"我想点一份炒饭和一杯白开水，可以吗？","questions":[{"q":{"ms":"Pilih permintaan yang paling sopan.","en":"Choose the most polite request.","zh":"选择最礼貌的请求。"},"options":[{"ms":"Boleh saya pesan satu hidangan ini?","en":"underneath","zh":"下方"},{"ms":"Bagi cepat!","en":"above","zh":"上方"},{"ms":"Aku mahu itu sekarang!","en":"in front","zh":"前面"},{"ms":"Oi, ambil pesanan!","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-give-directions-02","topicId":"ms-give-directions","difficulty":"beginner","title":"Berikan arah kepada pengunjung","titleEn":"Give directions to a visitor","titleZh":"为访客指路","body":"Terangkan laluan dari pintu masuk ke satu tempat dengan sekurang-kurangnya tiga arahan yang tersusun.","en":"Explain a route from the entrance to a place using at least three ordered instructions.","zh":"用至少三个有顺序的指示说明从入口到某个地点的路线。","example":"Masuk melalui pintu utama, berjalan terus dan belok kanan di kaunter.","exampleEn":"Enter through the main door, go straight and turn right at the counter.","exampleZh":"从正门进入，直走，然后在柜台处右转。","questions":[{"q":{"ms":"Arahan manakah patut diberikan terlebih dahulu?","en":"Which instruction should be given first?","zh":"应该先给出哪个指示？"},"options":[{"ms":"Masuk melalui pintu utama.","en":"underneath","zh":"下方"},{"ms":"Belok selepas tiba.","en":"above","zh":"上方"},{"ms":"Keluar dari bangunan.","en":"in front","zh":"前面"},{"ms":"Pulang ke rumah.","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-edit-affixes-02","topicId":"ms-edit-affixes","difficulty":"intermediate","title":"Baiki penggunaan imbuhan","titleEn":"Correct affix usage","titleZh":"修正词缀用法","body":"Semak ayat yang mengandungi kata terbitan. Kenal pasti kata dasar dan pilih imbuhan yang sesuai dengan maksud serta struktur ayat.","en":"Review sentences containing derived words. Identify the root and choose an affix that fits the meaning and sentence structure.","zh":"检查含有派生词的句子。找出词根，并根据意义和句子结构选择合适词缀。","example":"Murid itu sedang membaca bahan rujukan.","exampleEn":"The pupil is reading reference material.","exampleZh":"那名学生正在阅读参考资料。","questions":[{"q":{"ms":"Pilih kata kerja berimbuhan yang betul daripada kata dasar tulis.","en":"Choose the correctly affixed verb from the root tulis.","zh":"从词根tulis中选择词缀使用正确的动词。"},"options":[{"ms":"menulis","en":"underneath","zh":"下方"},{"ms":"memtulis","en":"above","zh":"上方"},{"ms":"mengtulis","en":"in front","zh":"前面"},{"ms":"penulisnya","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-summarise-notice-02","topicId":"ms-summarise-notice","difficulty":"intermediate","title":"Ringkaskan notis","titleEn":"Summarise a notice","titleZh":"概括通知内容","body":"Baca notis ringkas dan hasilkan ringkasan yang mengekalkan tujuan, tarikh, tempat dan tindakan yang perlu diambil. Elakkan menambah maklumat yang tiada dalam notis.","en":"Read a short notice and write a summary preserving its purpose, date, place and required action. Do not add information absent from the notice.","zh":"阅读简短通知并写出摘要，保留目的、日期、地点和所需行动。不要添加通知中没有的信息。","example":"Notis: Bengkel bermula pada pukul 9.00 pagi di dewan. Peserta perlu membawa komputer riba.","exampleEn":"Notice: The workshop begins at 9:00 a.m. in the hall. Participants must bring a laptop.","exampleZh":"通知：工作坊上午九点在礼堂开始。参加者须携带手提电脑。","questions":[{"q":{"ms":"Maklumat manakah wajib dikekalkan dalam ringkasan?","en":"Which information must be retained in the summary?","zh":"摘要中必须保留哪项信息？"},"options":[{"ms":"Masa, tempat dan keperluan peserta","en":"underneath","zh":"下方"},{"ms":"Warna pakaian penceramah","en":"above","zh":"上方"},{"ms":"Pendapat penulis tentang dewan","en":"in front","zh":"前面"},{"ms":"Cerita yang tidak dinyatakan","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-compare-viewpoints-02","topicId":"ms-compare-viewpoints","difficulty":"intermediate","title":"Bandingkan dua pandangan","titleEn":"Compare two viewpoints","titleZh":"比较两种观点","body":"Nyatakan persamaan dan perbezaan antara dua pandangan. Gunakan penanda perbandingan dan pastikan setiap pandangan diwakili secara adil.","en":"State similarities and differences between two viewpoints. Use comparison markers and represent each viewpoint fairly.","zh":"指出两种观点的相同点和不同点。使用比较衔接词，并公平呈现各方观点。","example":"Kedua-dua cadangan mengutamakan keselamatan, namun berbeza dari segi kos pelaksanaan.","exampleEn":"Both proposals prioritise safety, but differ in implementation cost.","exampleZh":"两项建议都优先考虑安全，但在实施成本方面有所不同。","questions":[{"q":{"ms":"Penanda manakah sesuai untuk menunjukkan pertentangan?","en":"Which marker is suitable for showing contrast?","zh":"哪个衔接词适合表示转折？"},"options":[{"ms":"Namun","en":"underneath","zh":"下方"},{"ms":"Selain itu","en":"above","zh":"上方"},{"ms":"Seterusnya","en":"in front","zh":"前面"},{"ms":"Contohnya","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-formal-email-02","topicId":"ms-formal-email","difficulty":"intermediate","title":"Tulis e-mel rasmi","titleEn":"Write a formal email","titleZh":"撰写正式电子邮件","body":"Tulis e-mel kepada pihak pentadbiran untuk meminta maklumat. Sertakan subjek yang khusus, sapaan, tujuan, butiran dan penutup yang sopan.","en":"Write an email to an administration office requesting information. Include a specific subject, greeting, purpose, details and polite closing.","zh":"给行政部门写一封询问信息的电子邮件。包括明确主题、称呼、目的、细节和礼貌结尾。","example":"Saya ingin mendapatkan penjelasan tentang dokumen yang perlu disertakan.","exampleEn":"I would like clarification about the documents that need to be included.","exampleZh":"我想了解需要附上的文件详情。","questions":[{"q":{"ms":"Apakah ciri subjek e-mel yang baik?","en":"What is a feature of a good email subject?","zh":"良好的电子邮件主题应具备什么特点？"},"options":[{"ms":"Ringkas dan menyatakan tujuan","en":"underneath","zh":"下方"},{"ms":"Panjang tanpa fokus","en":"above","zh":"上方"},{"ms":"Menggunakan singkatan tidak rasmi","en":"in front","zh":"前面"},{"ms":"Tidak berkaitan dengan isi","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-evaluate-source-02","topicId":"ms-evaluate-source","difficulty":"advanced","title":"Nilai kebolehpercayaan sumber","titleEn":"Evaluate source reliability","titleZh":"评估信息来源的可靠性","body":"Bandingkan dua sumber tentang isu yang sama. Semak pengarang, tarikh, bukti, tujuan penerbitan dan sokongan daripada sumber bebas sebelum membuat kesimpulan.","en":"Compare two sources on the same issue. Check authorship, date, evidence, publication purpose and corroboration from independent sources before concluding.","zh":"比较关于同一议题的两个来源。在得出结论前，检查作者、日期、证据、发布目的以及独立来源的佐证。","example":"Dakwaan yang disokong data terbuka dan kaedah yang jelas lebih mudah dinilai berbanding hantaran tanpa rujukan.","exampleEn":"A claim supported by open data and clear methods is easier to evaluate than an unsourced post.","exampleZh":"有公开数据和明确方法支持的主张，比没有出处的帖子更容易评估。","questions":[{"q":{"ms":"Apakah tindakan terbaik apabila dua sumber memberikan angka yang bercanggah?","en":"What is the best action when two sources provide conflicting figures?","zh":"当两个来源提供相互矛盾的数据时，最佳做法是什么？"},"options":[{"ms":"Semak kaedah, tarikh dan sumber asal kedua-duanya","en":"underneath","zh":"下方"},{"ms":"Pilih angka yang paling besar","en":"above","zh":"上方"},{"ms":"Percaya sumber yang paling popular","en":"in front","zh":"前面"},{"ms":"Abaikan semua bukti","en":"outside","zh":"外面"}],"answer":0}]},{"id":"ms-application-revise-argument-02","topicId":"ms-revise-argument","difficulty":"advanced","title":"Semak kekuatan hujah","titleEn":"Review argument strength","titleZh":"审查论证力度","body":"Nilai sama ada bukti benar-benar menyokong dakwaan. Bezakan korelasi daripada sebab-akibat dan nyatakan batasan bukti secara telus.","en":"Assess whether evidence genuinely supports a claim. Distinguish correlation from causation and state evidence limitations transparently.","zh":"评估证据是否真正支持主张。区分相关性与因果关系，并透明说明证据的局限。","example":"Peningkatan jualan berlaku serentak dengan kempen, tetapi faktor lain mungkin turut mempengaruhi hasil.","exampleEn":"Sales increased during the campaign, but other factors may also have influenced the result.","exampleZh":"销售额在活动期间上升，但其他因素也可能影响结果。","questions":[{"q":{"ms":"Mengapakah korelasi sahaja tidak membuktikan sebab-akibat?","en":"Why does correlation alone not prove causation?","zh":"为什么仅凭相关性不能证明因果关系？"},"options":[{"ms":"Hubungan itu mungkin dipengaruhi faktor lain","en":"underneath","zh":"下方"},{"ms":"Semua korelasi ialah kebetulan","en":"above","zh":"上方"},{"ms":"Data tidak pernah berguna","en":"in front","zh":"前面"},{"ms":"Sebab-akibat tidak boleh dikaji","en":"outside","zh":"外面"}],"answer":0}]}]);
 d.contentVersion="u3-ms-daily-0.2.0";
})();

